import unittest
from unittest import mock
from src import formatting
from src.formatting import preview_label, receipt_id

class PreviewLabelTests(unittest.TestCase):
    def test_longer_than_six_keeps_first_six(self):
        self.assertEqual(preview_label("abcdefghijklmnop"), "abcdef")
    def test_seven_characters_now_truncated(self):
        # v1 returned 7 characters unchanged; the approved v2 limit truncates them.
        self.assertEqual(preview_label("abcdefg"), "abcdef")
    def test_exactly_six_unchanged(self):
        self.assertEqual(preview_label("abcdef"), "abcdef")
    def test_five_characters_unchanged(self):
        self.assertEqual(preview_label("abcde"), "abcde")
    def test_empty_returns_empty(self):
        self.assertEqual(preview_label(""), "")
    def test_counts_python_unicode_characters(self):
        # Each of these is one code point but several UTF-8 bytes.
        self.assertEqual(preview_label("héllo wörld"), "héllo ")
        self.assertEqual(preview_label("日本語テキストです!"), "日本語テキス")
        self.assertEqual(preview_label("😀" * 10), "😀" * 6)
    def test_input_not_mutated(self):
        text = "abcdefghijkl"
        preview_label(text)
        self.assertEqual(text, "abcdefghijkl")
    def test_no_io(self):
        with mock.patch("builtins.open") as opened, mock.patch("builtins.print") as printed:
            preview_label("abcdefghijkl")
        opened.assert_not_called()
        printed.assert_not_called()

class ReceiptIndependenceTests(unittest.TestCase):
    def test_receipt_still_twelve_while_preview_is_six(self):
        text = "abcdefghijklmnop"
        self.assertEqual(receipt_id(text), "abcdefghijkl")
        self.assertEqual(preview_label(text), "abcdef")
    def test_receipt_keeps_value_between_preview_and_receipt_limits(self):
        self.assertEqual(receipt_id("abcdefg"), "abcdefg")
        self.assertEqual(receipt_id("abcdefghij"), "abcdefghij")
    def test_receipt_does_not_follow_preview_limit(self):
        with mock.patch.object(formatting, "PREVIEW_LIMIT", 3):
            self.assertEqual(receipt_id("abcdefghijklmnop"), "abcdefghijkl")

if __name__ == "__main__":
    unittest.main()

