import unittest
from src.formatting import preview_label, receipt_id, status_label

class StatusLabelTests(unittest.TestCase):
    def test_strips_and_uppercases(self):
        self.assertEqual(status_label("  ready \n"), "READY")
    def test_inner_whitespace_kept(self):
        self.assertEqual(status_label("\tin progress  "), "IN PROGRESS")
    def test_already_clean_uppercased(self):
        self.assertEqual(status_label("done"), "DONE")
    def test_empty_returns_empty(self):
        self.assertEqual(status_label(""), "")
    def test_whitespace_only_returns_empty(self):
        self.assertEqual(status_label(" \t\n "), "")
    def test_uses_python_str_upper(self):
        # str.upper() expands the German sharp s and uppercases non-ASCII letters.
        self.assertEqual(status_label(" straße "), "STRASSE")
        self.assertEqual(status_label(" héllo "), "HÉLLO")
    def test_preview_and_receipt_unchanged(self):
        text = "  abcdefghijklmnop"
        self.assertEqual(preview_label(text), "  abcd")
        self.assertEqual(receipt_id(text), "  abcdefghij")

if __name__ == "__main__":
    unittest.main()

